def solve(I):
    H,W=len(I),len(I[0])
    from collections import Counter
    cnt=Counter(v for row in I for v in row); bg=cnt.most_common(1)[0][0]
    others=[v for v,c in cnt.most_common() if v!=bg]
    mk=min(others,key=lambda v:c.count(v))
    # tile: connected non-(bg,mk) component bbox
    pts=[]
    seen=set()
    for r in range(H):
        for c in range(W):
            if I[r][c] not in (bg,mk) and (r,c) not in seen:
                stack=[(r,c)]; comp=set()
                while stack:
                    a,b=stack.pop()
                    if (a,b) in seen or (a,b) in comp: continue
                    comp.add((a,b)); seen.add((a,b))
                    for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+dr,b+dc
                        if 0<=x<H and 0<=y<W and I[x][y] not in (bg,mk) and (x,y) not in seen:
                            stack.append((x,y))
                rs=[p[0] for p in comp]; cs=[p[1] for p in comp]
                tile=[[I[r][c] for c in range(min(cs),max(cs)+1)] for r in range(min(rs),max(rs)+1)]
                break
    res=[row[:] for row in I]
    for r in range(H):
        for c in range(W):
            if I[r][c]==mk:
                oh,ow=len(tile),len(tile[0])
                tr=H-len(tile)//2  # offset
                oc=W-len(tile)//2
                for i in range(oh):
                    for j in range(ow):
                        rr=r-tr+i; cc=c-tile_offset(j)*0+j if False else c-(ow-1)//2+j
                        pass
                # place tile with its center on marker -> top-left = (r-oh//2, c-ow//2)
                tl=(r-len(tile)//2, c-len(tile[0])//2)
                for i in range(len(tile)):
                    for j in range(len(tile[0])):
                        nr,nc=tl[0]+i,tl[1]+j
                        if 0<=nr<H and 0<=nc<W: res[nr][nc]=tile[i][j]
    return res
for n in ['Demo pair 1','Demo pair 2','Demo pair 3']:
