from collections import Counter as Cnt

def f(I):
    H,W=len(I),len(I[0])
    cnt=Cnt(v for row in I for v in row); bg=cnt.most_common(1)[0][0]
    seen=set(); comps=[]
    for r in range(H):
        for c in range(W):
            if I[r][c]!=bg and (r,c) not in seen:
                st=[(r,c)]; comp=[]
                while st:
                    a,b=st.pop()
                    if (a,b) in seen: continue
                    seen.add((a,b)); comp.append((a,b))
                    for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+dr,b+dc
                        if 0<=x<H and 0<=y<W and I[x][y]!=bg and (x,y) not in seen:
                            st.append((x,y))
                comps.append(comp)
    tilecomp=max(comps,key=len)
    rs=[p[0] for p in tilecomp]; cs=[p[1] for p in tilecomp]
    tile=[[I[r][c] for c in range(min(cs),max(cs)+1)] for r in range(min(rs),max(rs)+1)]
    oh,ow=len(tile),len(tile[0])
    mk=[(r,c) for r in range(H) for c in range(W) if I[r][c]!=bg and not ((min(rs)<=r<=max(rs)) and (min(cs)<=c<=max(cs)))]
    res=[row[:] for row in I]
    for mr,mc in mk:
        tr=mr-(oh-1)//2; tc=mc-(ow-1)//2
        for i in range(oh):
            for j in range(ow):
                nr,nc=tr+i,tc+j
                if 0<=nr<H and 0<=nc<W: res[nr][nc]=tile[i][j]
    return res

